import numpy as np
from scipy.optimize import brentq
C2=np.array([1.16,2.67])
for s in [1,-1]:
 def vals(t):
  u=np.array([np.cos(t),np.sin(t)])
  v=np.array([np.cos(t+s*np.deg2rad(71)),np.sin(t+s*np.deg2rad(71))])
  C5=C2+1.5*u+2.65*v
  return np.linalg.norm(C5)
 ts=np.linspace(-np.pi,np.pi,1001)
 roots=[]
 for a,b in zip(ts,ts[1:]):
  if (vals(a)-2)*(vals(b)-2)<0:
   roots.append(brentq(lambda t:vals(t)-2,a,b))
 for t in roots:
  u=np.array([np.cos(t),np.sin(t)]); v=np.array([np.cos(t+s*np.deg2rad(71)),np.sin(t+s*np.deg2rad(71))])
  C3=C2+1.5*u; C5=C3+2.65*v
  print('s,t',s,np.rad2deg(t),'C3',C3,'C5',C5,'radius',np.linalg.norm(C5),'angle',np.rad2deg(np.arccos(np.dot(-u,v))))
